// How do I find out the main filtering condition set on a column in a spreadsheet?

// Examine the first rule of an active column filter and display its value in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare numeric data
worksheet.GetRange("A1").SetValue("Value");
worksheet.GetRange("A2").SetValue(10);
worksheet.GetRange("A3").SetValue(20);
worksheet.GetRange("A4").SetValue(30);
worksheet.GetRange("A5").SetValue(40);
worksheet.GetRange("A6").SetValue(50);

// Create a custom filter with two criteria (xlOr)
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(1, ">20", "xlOr", "<=30");

// Get the first filter object
let autoFilter = worksheet.AutoFilter;
let filters = autoFilter.Filters;

if (filters.length > 0) {
    let filter = filters[0];
    let criteria1 = filter.GetCriteria1();  // or filter.Criteria1

    worksheet.GetRange("C1").SetValue("Criteria1 (first condition):");
    worksheet.GetRange("D1").SetValue(criteria1);
}

// How do I check the second filtering rule on a column when two conditions are combined in a spreadsheet?

// Inspect the additional constraint set on a filter and display its value alongside the first rule in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare numeric data
worksheet.GetRange("A1").SetValue("Value");
worksheet.GetRange("A2").SetValue(5);
worksheet.GetRange("A3").SetValue(10);
worksheet.GetRange("A4").SetValue(15);
worksheet.GetRange("A5").SetValue(20);
worksheet.GetRange("A6").SetValue(25);

// Create a custom filter with xlAnd
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(1, ">=10", "xlAnd", "<=20");

// Get the filter and read both criteria
let autoFilter = worksheet.AutoFilter;
let filters = autoFilter.Filters;

if (filters.length > 0) {
    let filter = filters[0];

    worksheet.GetRange("C1").SetValue("Criteria2 (second condition):");
    worksheet.GetRange("D1").SetValue(filter.GetCriteria2());
}

// How do I tell if a column has an active filter applied to it in a spreadsheet?

// Confirm filtering is turned on for a specific column before reading its data in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare data
worksheet.GetRange("A1").SetValue("Score");
worksheet.GetRange("A2").SetValue(1);
worksheet.GetRange("A3").SetValue(2);
worksheet.GetRange("A4").SetValue(3);
worksheet.GetRange("A5").SetValue(4);
worksheet.GetRange("A6").SetValue(5);

// Apply a filter on column A
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(1, ">2", "xlOr");

// Inspect the filter
let autoFilter = worksheet.AutoFilter;
let filters = autoFilter.Filters;

if (filters.length > 0) {
    let filter = filters[0];

    worksheet.GetRange("C1").SetValue("Filter applied on column A:");
    worksheet.GetRange("D1").SetValue(filter.GetOn());    // or filter.On
}

// How do I find out what kind of filtering rule is applied to a column in a spreadsheet?

// Identify the filtering logic behind a column's filter to understand how rows are shown or hidden in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare data
worksheet.GetRange("A1").SetValue("Amount");
worksheet.GetRange("A2").SetValue(10);
worksheet.GetRange("A3").SetValue(20);
worksheet.GetRange("A4").SetValue(30);
worksheet.GetRange("A5").SetValue(40);
worksheet.GetRange("A6").SetValue(50);

// Apply a Top10 items filter
let dataRange = worksheet.GetRange("A1:A6");
dataRange.SetAutoFilter(1, "3", "xlTop10Items");

// Get the filter and read its operator
let autoFilter = worksheet.AutoFilter;
let filters = autoFilter.Filters;

if (filters.length > 0) {
    let filter = filters[0];

    worksheet.GetRange("C1").SetValue("Filter operator:");
    worksheet.GetRange("D1").SetValue(filter.GetOperator());   // or filter.Operator
}

// How do I get back to the overall auto-filter from one of its individual column filters in a spreadsheet?

// Trace a column filter up to its containing auto-filter to inspect the filtered range in a spreadsheet.

let worksheet = Api.GetActiveSheet();

// Prepare a small table
worksheet.GetRange("A1").SetValue("City");
worksheet.GetRange("B1").SetValue("Temperature");

worksheet.GetRange("A2").SetValue("London");
worksheet.GetRange("B2").SetValue(20);
worksheet.GetRange("A3").SetValue("Paris");
worksheet.GetRange("B3").SetValue(10);
worksheet.GetRange("A4").SetValue("Rome");
worksheet.GetRange("B4").SetValue(30);

// Apply a filter on column B
let dataRange = worksheet.GetRange("A1:B4");
dataRange.SetAutoFilter(2, ">15", "xlOr");

// Get the first ApiFilter
let autoFilter = worksheet.AutoFilter;
let filters = autoFilter.Filters;

if (filters.length > 0) {
    let filter = filters[0];
    let parentAutoFilter = filter.GetParent();     // or filter.Parent

    worksheet.GetRange("D1").SetValue("Parent AutoFilter range:");
    let parentRange = parentAutoFilter.GetRange();
    if (parentRange !== null) {
        worksheet.GetRange("D2").SetValue(parentRange.GetAddress());
    }

    worksheet.GetRange("D4").SetValue("This filter belongs to the sheet:");
    worksheet.GetRange("D5").SetValue(parentAutoFilter.Parent.GetName());
}
